from dataclasses import dataclass, field, fields
from typing import Any, List, Optional, Dict

class TdObject:
    __td_type__: str

    def to_dict(self) -> Dict[str, Any]:
        data = {'@type': self.__td_type__}
        for f_ in fields(self):
            # Skip __td_type__ field (already set above)
            if f_.name == '__td_type__':
                continue
            val = getattr(self, f_.name)
            if val is None:
                continue
            if isinstance(val, TdObject):
                data[f_.name] = val.to_dict()
            elif isinstance(val, list):
                data[f_.name] = [
                    v.to_dict() if isinstance(v, TdObject) else v
                    for v in val
                ]
            else:
                data[f_.name] = val
        return data

